  // element we will write.  It's not safe to read it until numSent has been
  // incremented. Thus there are really only (SB_QUEUE_BOOL_1_SIZE - 1)
  // elements in the queue.
  *numDropped = (numNew <= SB_QUEUE_BOOL_1_SIZE - 1) ? 0 : numNew - SB_QUEUE_BOOL_1_SIZE + 1;

