pub struct sys_nominal_monitor_process_sys_nominal_monitor_thread {
  // PLACEHOLDER MARKER STATE VARS
  frame_period: i32,
  last_index: u32,
  prev_user_ch: hamr::ScheduleChannels,
  next_user_ch: hamr::ScheduleChannels,
  components: observers::components::ComponentContracts,
  sys_assert_last_index: u32,
  sys_assert: observers::sys_nominal::SysAssert_nominal,
}

impl sys_nominal_monitor_process_sys_nominal_monitor_thread {
  pub fn new() -> Self
  {
    Self {
      frame_period: 0,
      last_index: u32::MAX,
      prev_user_ch: [0; hamr::hamr_ScheduleChannels_DIM_0],
      next_user_ch: [0; hamr::hamr_ScheduleChannels_DIM_0],
      components: observers::components::ComponentContracts::new(),
      sys_assert_last_index: u32::MAX,
      sys_assert: observers::sys_nominal::SysAssert_nominal::new(),
    }
  }

  pub fn initialize<API: sys_nominal_monitor_process_sys_nominal_monitor_thread_Put_Api> (
    &mut self,
    api: &mut sys_nominal_monitor_process_sys_nominal_monitor_thread_Application_Api<API>)
  {
    log_info("initialize entrypoint invoked");
  }

  pub fn timeTriggered<API: sys_nominal_monitor_process_sys_nominal_monitor_thread_Full_Api> (
    &mut self,
    api: &mut sys_nominal_monitor_process_sys_nominal_monitor_thread_Application_Api<API>)
  {
    self.gumbo_monitor(api);
    self.sys_assert_monitor(api);
  }

  pub fn notify(
    &mut self,
    channel: microkit_channel)
  {
    // this method is called when the monitor does not handle the passed in channel
    match channel {
      _ => {
        log_warn_channel(channel)
      }
    }
  }

  pub fn gumbo_monitor<API: sys_nominal_monitor_process_sys_nominal_monitor_thread_Full_Api> (
    &mut self,
    api: &mut sys_nominal_monitor_process_sys_nominal_monitor_thread_Application_Api<API>)
  {
    let state = api.get_sched_state();

    if self.last_index == u32::MAX {
      let schedule = api.get_sched_schedule();
      buildUserChannelTables(
        &schedule, &mut self.prev_user_ch, &mut self.next_user_ch);
    }

    // Detect schedule wraparound: if the current timeslice index is not
    // greater than the last one seen, the schedule has started a new frame
    if state.current_timeslice <= self.last_index {
      self.frame_period = self.frame_period + 1;
    }

    let idx = state.current_timeslice as usize;
    let mut view = MonitorView { api: api };

    if self.last_index == u32::MAX {
      // First compute phase, check initialization guarantees
      self.components.on_init(&mut view, &mut LogSink);
    } else if let Some(prev) = thread_of(self.prev_user_ch[idx]) {
      // the thread that just yielded: check its post-condition
      self.components.on_complete(prev, &mut view, &mut LogSink);
    }

    // the thread that runs next: save its pre-state, check its pre-condition
    if let Some(next) = thread_of(self.next_user_ch[idx]) {
      self.components.on_dispatch(next, &mut view, &mut LogSink);
    }

    self.last_index = state.current_timeslice;
  }

  pub fn sys_assert_monitor<API: sys_nominal_monitor_process_sys_nominal_monitor_thread_Full_Api> (
    &mut self,
    api: &mut sys_nominal_monitor_process_sys_nominal_monitor_thread_Application_Api<API>)
  {
    let state = api.get_sched_state();

    if self.sys_assert_last_index == u32::MAX {
      let schedule = api.get_sched_schedule();
      buildUserChannelTables(
        &schedule, &mut self.prev_user_ch, &mut self.next_user_ch);
      observers::sys_nominal::SysAssert_nominal::validate_schedule(&schedule, thread_of, &mut LogSink);
    }

    let idx = state.current_timeslice as usize;

    if self.sys_assert_last_index == u32::MAX {
      // First compute phase — initialize ready set and cascade
      self.sys_assert.on_init();
      self.sys_assert_last_index = state.current_timeslice;
      return;
    }

    // the thread that just yielded: fire its transition and check the assertions
    let mut view = MonitorView { api: api };
    if let Some(prev) = thread_of(self.prev_user_ch[idx]) {
      self.sys_assert.on_complete(prev, &mut view, &mut LogSink);
    }

    self.sys_assert_last_index = state.current_timeslice;
  }
}

